{
  "name": "read",
  "description": "Read the contents of a file. Supports text files and images (jpg, png, gif, webp). Images are sent as attachments. For text files, output is truncated to 2000 lines or 50KB (whichever is hit first). Use offset/limit for large files. When you need the full file, continue with offset until complete.",
  "parameters": {
    "type": "object",
    "required": [
      "path"
    ],
    "properties": {
      "path": {
        "type": "string",
        "description": "Path to the file to read (relative or absolute)"
      },
      "offset": {
        "type": "number",
        "description": "Line number to start reading from (1-indexed)"
      },
      "limit": {
        "type": "number",
        "description": "Maximum number of lines to read"
      }
    }
  }
}

{
  "name": "write",
  "description": "Write content to a file. Creates the file if it doesn't exist, overwrites if it does. Automatically creates parent directories.",
  "parameters": {
    "type": "object",
    "required": [
      "path",
      "content"
    ],
    "properties": {
      "path": {
        "type": "string",
        "description": "Path to the file to write (relative or absolute)"
      },
      "content": {
        "type": "string",
        "description": "Content to write to the file"
      }
    }
  }
}

{
  "name": "edit",
  "description": "Edit a single file using exact text replacement. Every edits[].oldText must match a unique, non-overlapping region of the original file. If two changes affect the same block or nearby lines, merge them into one edit instead of emitting overlapping edits. Do not include large unchanged regions just to connect distant changes.",
  "parameters": {
    "type": "object",
    "required": [
      "path",
      "edits"
    ],
    "properties": {
      "path": {
        "type": "string",
        "description": "Path to the file to edit (relative or absolute)"
      },
      "edits": {
        "type": "array",
        "items": {
          "type": "object",
          "required": [
            "oldText",
            "newText"
          ],
          "properties": {
            "oldText": {
              "type": "string",
              "description": "Exact text for one targeted replacement. It must be unique in the original file and must not overlap with any other edits[].oldText in the same call."
            },
            "newText": {
              "type": "string",
              "description": "Replacement text for this targeted edit."
            }
          }
        },
        "description": "One or more targeted replacements. Each edit is matched against the original file, not incrementally. Do not include overlapping or nested edits. If two changes touch the same block or nearby lines, merge them into one edit instead."
      }
    }
  }
}

{
  "name": "bash",
  "description": "Execute a bash command in the current working directory. Returns combined stdout and stderr. Output is truncated to last 2000 lines or 50KB (whichever is hit first). If truncated, full output is saved to a temp file. Optionally provide a timeout in seconds.",
  "parameters": {
    "type": "object",
    "required": [
      "command"
    ],
    "properties": {
      "command": {
        "type": "string",
        "description": "Bash command to execute"
      },
      "timeout": {
        "type": "number",
        "description": "Timeout in seconds (optional, no default timeout)"
      }
    }
  }
}

{
  "name": "remember",
  "description": "把一件事写进长期记忆，以后每次对话都可能被想起来。适合：对方的偏好、家人朋友宠物、长期目标、重要经历。对方说「我打算 / 我准备 / 下周开始……」这类还没发生的计划时用 kind=intention，并尽量给 expiresInDays——到期后它自动变成普通事实，不会一直挂在「打算」里。不适合：一次性的琐事、马上就会变的信息。**用户用「以后 / 记住 / 下次」这类话纠正你、或给你立规矩时，必须立刻用本工具记一条 kind=preference、taught=true 的记忆**——不要只在这一次照做，也不要只是口头答应；记的是那条规矩本身（做什么 / 不做什么），不是这次对话的经过。若教的是方法 / 步骤（「这类活怎么做」）而非规矩，在具备 partner_skill_write 工具时另写成技能文件沉淀；规矩本身仍落 preference。两件事不互斥：规矩进偏好（永不删），方法进技能（按需取用）。",
  "parameters": {
    "type": "object",
    "required": [
      "content"
    ],
    "properties": {
      "content": {
        "type": "string",
        "description": "要记住的内容，一句话，用第三人称或原话"
      },
      "kind": {
        "type": "string",
        "enum": [
          "fact",
          "episode",
          "preference",
          "entity",
          "intention"
        ],
        "description": "fact=事实 / episode=经历过的事 / preference=偏好 / entity=人事物 / intention=打算（我打算…）"
      },
      "expiresInDays": {
        "type": "number",
        "description": "kind=intention 时有效：多少天后这条打算自动降级为普通事实。1..365，不传 = 不过期。",
        "minimum": 1,
        "maximum": 365
      },
      "importance": {
        "type": "number",
        "description": "重要程度 0..1，默认 0.7",
        "minimum": 0,
        "maximum": 1
      },
      "taught": {
        "type": "boolean",
        "description": "用户教你规矩（「以后… / 记住… / 下次…」）时为 true：这条会标成 taught 来源。普通事实不填。"
      },
      "scope": {
        "anyOf": [
          {
            "type": "string",
            "const": "auto"
          },
          {
            "type": "string",
            "const": "project"
          }
        ],
        "description": "auto=默认归属；project=挂到项目记忆里（只在聊这个项目时被想起）。项目相关的口径（怎么构建、怎么部署、踩过什么坑）用 project。你负责多个项目时，要带 project 参数指名写进哪个。"
      },
      "project": {
        "type": "string",
        "description": "scope=project 时用：项目名（负责项目清单里的名字）。你负责多个项目时必填；只负责一个或会话已绑定项目时不用填。"
      }
    }
  }
}

{
  "name": "recall",
  "description": "在长期记忆里检索。和对方有关的事想不起来了，先用它查，不要猜。当前对话的上下文里通常已经带了相关记忆，只有在不够用时才调用。",
  "parameters": {
    "type": "object",
    "required": [
      "query"
    ],
    "properties": {
      "query": {
        "type": "string",
        "description": "要查什么，用关键词或一句话"
      },
      "limit": {
        "type": "number",
        "description": "最多返回几条，默认 5"
      }
    }
  }
}

{
  "name": "set_reminder",
  "description": "定一个到点提醒。时间写 ISO 8601（带时区），例如 2026-10-29T08:00:00+08:00。提醒会落库，进程重启也不会丢。要重复时，`at` 只用来定「几点」，服务端会自动推到下一次符合规则的时间，再补 `repeat`：每天 = daily；每周 = weekly + weekdays（0 周日 … 6 周六）；每月 = monthly + dayOfMonth（1–31）。区间结束用 `until`（ISO 8601，含当天）。",
  "parameters": {
    "type": "object",
    "required": [
      "text",
      "at"
    ],
    "properties": {
      "text": {
        "type": "string",
        "description": "到点要提醒的内容"
      },
      "at": {
        "type": "string",
        "description": "第一次触发时间，ISO 8601"
      },
      "repeat": {
        "anyOf": [
          {
            "type": "string",
            "const": "none"
          },
          {
            "type": "string",
            "const": "daily"
          },
          {
            "type": "string",
            "const": "weekly"
          },
          {
            "type": "string",
            "const": "monthly"
          }
        ],
        "description": "频率；缺省 = 一次性"
      },
      "weekdays": {
        "type": "array",
        "items": {
          "type": "number"
        },
        "description": "weekly 用：0 = 周日，1 = 周一 … 6 = 周六，可多选"
      },
      "dayOfMonth": {
        "type": "number",
        "description": "monthly 用：1–31；没有这一天的月份按月末算"
      },
      "until": {
        "type": "string",
        "description": "区间结束日期，ISO 8601（含当天）"
      }
    }
  }
}

{
  "name": "recall_sessions",
  "description": "在**以前所有对话的原文**里找一句话（含执事会话、群聊、任务专线）。记忆想不起来、或者要确认「上次是不是聊过这件事」时用它；只读，不改任何东西。返回会话标题、时间和命中处前后各约 100 字；查不到就返回空。",
  "parameters": {
    "type": "object",
    "required": [
      "query"
    ],
    "properties": {
      "query": {
        "type": "string",
        "description": "要找的内容，至少 2 个字；用关键词或一句话"
      },
      "days": {
        "type": "number",
        "description": "只搜最近多少天，默认 30",
        "minimum": 1,
        "maximum": 365
      },
      "limit": {
        "type": "number",
        "description": "最多返回几条，默认 5",
        "minimum": 1,
        "maximum": 20
      }
    }
  }
}

{
  "name": "persona_recall",
  "description": "在**主人的个人记忆库**（跨越很多年的原始记录与分析）里检索证据条目，每条带出处 id。适用：本地记忆想不起来 / 查很久以前（如去年、2024 年）的事 / 主人要求给原文出处。**查不到 ≠ 没有这回事**：返回里有『不确定』说明时照转述，不要编。与 recall 分工：recall 查最近与偏好，persona_recall 查一生；先 recall 再 persona_recall。",
  "parameters": {
    "type": "object",
    "required": [
      "query"
    ],
    "properties": {
      "query": {
        "type": "string",
        "description": "要查什么，用关键词或一句话"
      },
      "limit": {
        "type": "number",
        "description": "每组最多返回几条，默认 5",
        "minimum": 1,
        "maximum": 20
      }
    }
  }
}

{
  "name": "skill",
  "description": "取一份技能手册（完整流程）。会话的 skills 索引里列出了可用技能；要按某个流程引导对方时，先调它拿到手册，再照着做。",
  "parameters": {
    "type": "object",
    "required": [
      "name"
    ],
    "properties": {
      "name": {
        "type": "string",
        "description": "技能名，必须是索引里列出的名字"
      }
    }
  }
}

{
  "name": "send_to_agent",
  "description": "给另一位执事递一条话（只送到对方的会话里，主人看不到原文）。适合：把自己查到的事交给对口的执事、跟对方对一下口径。target 写执事的名字或领域；重名时用「名字·领域」。一次只说一件事、一条话别拆成好几条（每轮最多 3 条）；收到别人递来的话那一轮不能再往外递。",
  "parameters": {
    "type": "object",
    "required": [
      "target",
      "message"
    ],
    "properties": {
      "target": {
        "type": "string",
        "description": "执事的名字或领域（重名用「名字·领域」）"
      },
      "message": {
        "type": "string",
        "description": "要递的话，用自己的话写，不超过 4000 字"
      }
    }
  }
}

{
  "name": "save_skill_advice",
  "description": "把技能分类评估的结果一次性写进建议快照（设置页的三栏与频率就是读它）。只在主人让你评估技能库、并且你已经逐条判断完之后调用一次。清单里没评估到的技能不会被覆盖——快照会保留它们原来的建议。它不改变任何技能的开关：主人会回设置页自己决定采纳哪些。",
  "parameters": {
    "type": "object",
    "required": [
      "items"
    ],
    "properties": {
      "items": {
        "type": "object",
        "patternProperties": {
          "^.*$": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "maxItems": 3,
            "minItems": 3
          }
        },
        "description": "技能名 → [bucket, frequency, reason] 三元素数组。bucket: keep(建议开启)|scene(按场景)|skip(建议不开)；frequency: daily|weekly|monthly|rare（rare 应配 skip）；reason ≤20 字"
      }
    }
  }
}

{
  "name": "delegate",
  "description": "把一件需要多步动手的活派给外面的工人（领域负责人/执行者）去做。适合：要改多个文件、要跑命令、要查证之后再动手的任务；**以及在手机上操作 App**——打开某个 App、点按钮、输入文字、翻页、看屏幕上显示了什么。不适合：回答问题、闲聊、一次 read 就能答的事、需要边做边问对方的事。**派出去后会立即返回任务单号，不会占住这一轮对话；后台跑完会有一条汇报写进会话。**所以返回后直接告诉用户「已派发，完成后会汇报」即可，不要等结果、不要反复查询、不要重复派。填 `domain` 把活交给对应领域的负责人。**领域名必须是小写 ASCII**（小写字母、数字、连字符，如 `frontend` / `desktop-shell`）；当前已有领域：inbox / beta / alpha / calendar / forge。不填则按旧路径直接派 worker。**派新活时必须带 `project`（已登记的项目名或 id）**；手机/设备 worker 这类不落本机磁盘的活可省 `project`（设备活豁免）；本机活没有可用项目时会返回 `{\"error\":\"needs_project\"}` 并列出已有项目——先问用户要建哪个项目，用 `propose_project` 提交、等用户在设置里确认，再派。如果上一轮派出去的活卡住了、你问了用户一个问题、用户刚回答了你，用 `resume: true` 接着原单跑：`requirement` 里只写用户的那句回答（比如「验证码 1234」），不要重述整个任务，**更不要重新派**——重派会让对方从头再做一遍。对方在回答你上一轮的问题时，他这句话本身就是要交回去的内容：直接拿它调 resume，不要再反问一遍，也不要自己替它把剩下的事做完。会话里没有可续的单时会按新活派，并在结果里告诉你。**注意（只讲文件路径，不是能力限制）**：工人写文件时用相对路径（如 `summary.md`），不要指定工作目录之外的绝对路径；产物最后落在 chancellor 的 runs/<ticket>/ 下，不在你指定的绝对位置。工人在手机上干活时，它看到的是手机屏幕、点的是手机上的按钮——**它碰不到你电脑上的文件**；反过来，它交回来的是一句话，不是手机里的截图或文件。**任务书按四段写**：目标 / 怎么算好 / 可自主范围 / 必须请示。你若带「岗位契约」，后两段直接按契约的「决策分级」「验收标准」填写；没有契约就按常理写清边界。**多步活要写 `steps`**：一件事如果有 ≥3 个动作、或者要跨文件改，就用 steps 列出可核对的动作序列（≤12 条，每条一句话说清做什么、怎么算做到）；一句话就能说完的小活不写。工人回报「需要你」（need_input / need_decision / need_action）时，答得了就答；一时答不了，明确告诉它「这一项先跳过，继续其余部分，这项回头再补」，别让整单停在一件小事上。**派活前告诉工人按四行回报**（回报开头写「给<你的名字>：」，不要把任务原样发回给派活的人）：\n状态：完成 / 部分完成 / 卡住\n结果：一句话说清做成了什么（不是过程）\n证据：拿什么证明的（改了哪个文件 / 跑了什么命令 / 看到什么输出）\n解锁：卡住时，下一步需要谁做什么；没卡住就写「无」\n\n【裁决纪律】\n- 继续干，别反复请示：「要不要我继续」是在浪费人的一天；计划里的事一口气做完。\n- 只有四种情况停下问人：① 不可逆或破坏性的操作；② 安全敏感的动作；③ 工作目录之外的副作用（合并、推共享分支、发布）；④ 计划烂到往前每一步都是猜。\n- 四停之外一律自己裁决，并记一行账：`裁决：<决定了什么> — <为什么> — <错了的代价>`；写进给主人的汇报或任务单留言，让人事后看得见、能推翻。\n- 一个错的裁决，人看得见、也能让我改；一个卡着等回答的会话，花掉的是人一整天。",
  "parameters": {
    "type": "object",
    "required": [
      "requirement"
    ],
    "properties": {
      "requirement": {
        "type": "string",
        "description": "要做的事，按四段写清：① 目标（要达成什么）② 怎么算好（验收标准）③ 可自主范围（哪些你可以自己定）④ 必须请示（哪些要先问你）。带岗位契约时，后两段照契约的「决策分级」「验收标准」写。resume 时只写用户的那句回答，不要重述任务。要写文件时给相对路径；要读的文件给绝对路径没问题。"
      },
      "project": {
        "type": "string",
        "description": "已登记的项目名或 id。派新活时必填；续跑（resume）时可以省略，沿用原单的项目。不知道有哪些项目时，先不带，工具会返回 needs_project 和项目清单。"
      },
      "domain": {
        "type": "string",
        "description": "领域负责人的领域名，**必须是小写 ASCII**（小写字母、数字、连字符，如 `frontend` / `desktop-shell`）。当前已有领域：inbox / beta / alpha / calendar / forge。填了就把活交给该领域负责人；不填则直接派 worker（兼容旧行为）。"
      },
      "targetDevice": {
        "type": "string",
        "description": "把活派给**另一台电脑**的 harness 执行（设备矩阵）。填中结名册里的设备 id。`\"auto\"` = 电脑自己挑一台（DEVICE_AUTO_DISPATCH 开启时）：**优先主机**（用户在设置里指定的那台），主机满载或离线才按忙碌度外流到别的机器；挑不出就在本机执行并说明原因；不填仍是本机执行。设备描述（如「存储机」）与主机位可在 /relay/overview 看到，供点名参考，不参与自动挑选。填了就跑远程分支：本机的项目登记表不参与，`project` 由目标机判；目标离线会直接失败（不排队）。"
      },
      "resume": {
        "type": "boolean",
        "description": "接着上一张单跑（上次派出去的活卡住了、你问了用户、用户刚回答时用）。不填 = 新派一件。"
      },
      "requestId": {
        "type": "string",
        "description": "幂等键。同一次派活在重试/重启后要用同一个 id，工具会返回原任务单号，不会重复起一张单。不填时服务端按会话 + 需求自动生成。"
      },
      "steps": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "这条要求拆成的可核对动作序列（≤12 条，每条 ≤200 字）。多步活（≥3 个动作或跨文件）必写；一句话的小活不写。验收项用 `验：` 开头写（如 `验：npm test 全绿`），其余每条算一个动作；验收项会在任务详情里单独列出，不要和动作混在一句里。"
      }
    }
  }
}

{
  "name": "propose_project",
  "description": "在用户已选定工作区的前提下，提出新建一个项目根目录。它只提交待用户确认的请求，**不会创建目录、也不会登记项目**；用户在项目设置里确认后才真正建目录。只有用户明确要新建一个项目（新的根目录）时才调用；项目内部的子目录不需要、也不应该新建项目。",
  "parameters": {
    "type": "object",
    "required": [
      "name",
      "path"
    ],
    "properties": {
      "name": {
        "type": "string",
        "description": "项目名，给用户看的短名，例如 手机端 / 桌面壳 / 文档站"
      },
      "path": {
        "type": "string",
        "description": "工作区内的相对路径，例如 projects/新的小工具；不要写绝对路径，不要包含 .."
      }
    }
  }
}

{
  "name": "ask_user",
  "description": "向用户提一个结构化问题，等他回答后再继续。只在**真有分叉**时问：比如两条都合理的路线要人选、缺一个只有他知道的事实、要不要动一件不可逆的事。**一次只问一个**；选项给 2-3 个互斥项，recommended 填你建议的下标（可选）。**能从文件 / 记忆 / 工具查到的事实先自己查，别问人**；也不要拿它问确认（要批准的操作走审批）。如果用户的回答会影响整张任务单，用 delegate 的 resume 把答复交回去。",
  "parameters": {
    "type": "object",
    "required": [
      "question"
    ],
    "properties": {
      "question": {
        "type": "string",
        "description": "要问的一句话，≤200 字"
      },
      "options": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "2-3 个互斥选项，每个 ≤60 字；没有明确选项时省略"
      },
      "recommended": {
        "type": "number",
        "description": "建议项在 options 里的下标（0 起）；可选"
      }
    }
  }
}

{
  "name": "report_progress",
  "description": "长任务做到一半时，主动对主人说一句进展（**不会结束本轮**）。适合：跨了好几步、要跑好几分钟的活，中间有一句值得让人先知道的话（「已经定位到问题，正在改」「前两步做完，第三步要再等一会儿」）。每次不超过 200 字，一条说一件事；每轮最多 3 条，超了就合并成一条。**不适合**：一句话就能汇报完的短活、纯寒暄、把最终结论拆成好几条。这句话会出现在主人正在看的对话流里；没开流就收不到，也不会补写历史。",
  "parameters": {
    "type": "object",
    "required": [
      "message"
    ],
    "properties": {
      "message": {
        "type": "string",
        "description": "要说的那一句，不超过 200 字"
      }
    }
  }
}

{
