{
  "name": "routine_manage",
  "description": "管理**你自己**的例行规则（到点自动跑一轮）：create 建、disable 停用、enable 启用、delete 删除。只能动自己名下的规则，动别人的一律当找不到；每个执事最多 10 条活动规则。create 需要 name（≤40 字）、prompt（这一轮要做什么）、triggers（cron 五段 / interval≥60s / once ISO / event）、sessionMode（persistent 复用会话 / fresh 每轮全新），可选 untilNote（完成条件，一句话；每轮跑完由你判断达成没有，达成即自动停用、保留历史）与 maxRuns（跑满 N 次自动停）。其余动作带 id。例：主人说「你每周五自己盘点」，就用 create 建一条 cron「0 18 * * 5」的周盘点规则。\n按周期盘点自己干过的活时：读自己的 work 工作履历，用一段自然语言说清这一阵子\n接了几单、成了几单、哪一单卡过、有什么该记取的教训（不打分、不列 KPI 数字）；\n把这段总结用 remember 落一条 kind=episode 的记忆，再向主人汇报。\n不要自己悄悄创建回顾规则——要主人配，或主人说一句你再用 routine_manage 建。",
  "parameters": {
    "type": "object",
    "required": [
      "action"
    ],
    "properties": {
      "action": {
        "type": "string",
        "enum": [
          "create",
          "disable",
          "enable",
          "delete"
        ],
        "description": "create=建 / disable=停用 / enable=启用 / delete=删除"
      },
      "id": {
        "type": "string",
        "description": "disable / enable / delete 必填：自己的规则 id"
      },
      "name": {
        "type": "string",
        "description": "create 必填，规则名 ≤40 字"
      },
      "prompt": {
        "type": "string",
        "description": "create 必填，每次触发要执行的指令正文"
      },
      "triggers": {
        "type": "array",
        "items": {
          "type": "object"
        },
        "description": "create 必填，非空数组。cron={type:'cron',expr:'0 18 * * 5'} / interval={type:'interval',seconds:3600} / once={type:'once',at:'ISO时间'} / event={type:'event',kind:'delegation'|'tool'|'phase',match?:{}}"
      },
      "sessionMode": {
        "type": "string",
        "enum": [
          "persistent",
          "fresh"
        ],
        "description": "create 可选：persistent=复用主会话 / fresh=每轮全新（缺省 persistent）"
      },
      "untilNote": {
        "type": "string",
        "description": "create 可选：完成条件的文字说明（≤200 字）。每轮跑完由你判断达成没有；达成时在回复最后单独一行写 [[routine-done]]，规则会自动停用（不删）。"
      },
      "maxRuns": {
        "type": "number",
        "description": "create 可选：跑满 N 次自动停（1..1000）；不传 = 不限次数",
        "minimum": 1,
        "maximum": 1000
      }
    }
  }
}

